/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'
import { parseGraph, findCycle, timings, pack, GraphError } from './graph.js'

function fail(message, code = 2) {
  process.stderr.write(message + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
let mode = null
let workers = 0
if ((args.length === 1 && (args[0] === 'waves' || args[0] === 'explain')) || (args.length === 2 && args[0] === 'pack')) {
  mode = args[0]
  if (mode === 'pack') {
    if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
    workers = Number(args[1])
  }
} else {
  fail('error: usage: cli.js waves|explain|pack <workers>')
}

let graph
try {
  graph = parseGraph(readFileSync(0, 'utf8'))
} catch (e) {
  if (e instanceof GraphError) fail(e.message)
  throw e
}
const cycle = findCycle(graph)
if (cycle) fail('error: cycle: ' + cycle.join(' -> '), 3)

const names = [...graph.keys()].sort()
const out = []
if (mode === 'pack') {
  const { lanes, makespan } = pack(graph, names, workers)
  lanes.forEach((lane, i) => {
    out.push(`worker ${i}:` + lane.map((r) => ` ${r.name}@${r.start}-${r.finish}`).join(''))
  })
  out.push(`makespan ${makespan}`)
} else {
  const { info, total } = timings(graph, names)
  if (mode === 'waves') {
    const waves = []
    for (const n of names) (waves[info.get(n).depth] ??= []).push(n)
    waves.forEach((w, k) => out.push(`wave ${k}: ${w.join(' ')}`))
  } else {
    for (const n of names) {
      const t = info.get(n)
      out.push(`${n} start=${t.start} finish=${t.finish} depth=${t.depth}`)
    }
  }
  out.push(`total ${total}`)
}
process.stdout.write(out.join('\n') + '\n')
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261026T225247Z/cell-5Rioel/src/graph.js","content":"export class GraphError extends Error {}

const NAME = /^[A-Za-z0-9_.-]+$/

/** Parses the input into Map<name, {cost: bigint, deps: string[] sorted}>. */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const graph = new Map()
  const depLines = []
  lines.forEach((raw, idx) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    const n = idx + 1
    if (w[0] === 'task') {
      if (w.length !== 3) throw new GraphError(`error: line ${n}: expected task <name> <cost>`)
      if (!NAME.test(w[1])) throw new GraphError(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new GraphError(`error: line ${n}: cost must be a non-negative integer`)
      if (graph.has(w[1])) throw new GraphError(`error: line ${n}: task ${w[1]} is declared twice`)
      graph.set(w[1], { cost: BigInt(w[2]), deps: new Set() })
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new GraphError(`error: line ${n}: expected dep <name> <dependency>...`)
      for (const name of w.slice(1)) {
        if (!NAME.test(name)) throw new GraphError(`error: line ${n}: invalid task name ${name}`)
      }
      depLines.push(w.slice(1))
    } else {
      throw new GraphError(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const names of depLines) {
    for (const name of names) if (!graph.has(name)) throw new GraphError(`error: unknown task ${name}`)
  }
  for (const [name, ...deps] of depLines) for (const d of deps) graph.get(name).deps.add(d)
  for (const t of graph.values()) t.deps = [...t.deps].sort()
  return graph
}

export function findCycle(graph) {
  const state = new Map()
  const stack = []
  const visit = (n) => {
    state.set(n, 1)
    stack.push(n)
    for (const d of graph.get(n).deps) {
      if (state.get(d) === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!state.has(d)) {
        const c = visit(d)
        if (c) return c
      }
    }
    stack.pop()
    state.set(n, 2)
    return null
  }
  for (const n of [...graph.keys()].sort()) {
    if (!state.has(n)) {
      const c = visit(n)
      if (c) return c
    }
  }
  return null
}

export function timings(graph, names) {
  const info = new Map()
  const calc = (n) => {
    if (info.has(n)) return info.get(n)
    let start = 0n
    let depth = 0
    for (const d of graph.get(n).deps) {
      const t = calc(d)
      if (t.finish > start) start = t.finish
      if (t.depth + 1 > depth) depth = t.depth + 1
    }
    const r = { start, finish: start + graph.get(n).cost, depth }
    info.set(n, r)
    return r
  }
  let total = 0n
  for (const n of names) {
    const r = calc(n)
    if (r.finish > total) total = r.finish
  }
  return { info, total }
}

export function pack(graph, names, workerCount) {
  const prio = new Map()
  const calc = (n) => {
    if (prio.has(n)) return prio.get(n)
    prio.set(n, 0n)
    prio.set(n, graph.get(n).cost)
    return prio.get(n)
  }
  // longest chain beginning at n: needs dependents
  const dependents = new Map(names.map((n) => [n, []]))
  for (const n of names) for (const d of graph.get(n).deps) dependents.get(d).push(n)
  const chain = new Map()
  const longest = (n) => {
    if (chain.has(n)) return chain.get(n)
    let best = 0n
    for (const m of dependents.get(n)) {
      const v = longest(m)
      if (v > best) best = v
    }
    const r = graph.get(n).cost + best
    chain.set(n, r)
    return r
  }
  void calc
  const finish = new Map()
  const started = new Set()
  const lanes = Array.from({ length: workerCount }, () => [])
  const freeAt = new Array(workerCount).fill(0n)
  let t = 0n
  let makespan = 0n
  while (started.size < names.length) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const n of names) {
        if (started.has(n)) continue
        if (!graph.get(n).deps.every((d) => finish.has(d) && finish.get(d) <= t)) continue
        if (pick === null || longest(n) > longest(pick)) pick = n
      }
      if (pick === null) break
      const f = t + graph.get(pick).cost
      started.add(pick)
      finish.set(pick, f)
      lanes[w].push({ name: pick, start: t, finish: f })
      freeAt[w] = f
      if (f > makespan) makespan = f
    }
    if (started.size === names.length) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  return { lanes, makespan }
}
"}

