import { readFileSync } from 'node:fs'

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function parse(text) {
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    const fail = (r) => new Fail(`error: line ${i + 1}: ${r}`)
    const num = (v, field, least) => {
      if (!INT.test(v) || BigInt(v) < BigInt(least)) throw fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = f[0]
    if (d === 'bucket' || d === 'window' || d === 'route') {
      if (events.length) throw fail('declarations must come before the first event')
    }
    if (d === 'bucket') {
      if (f.length !== 5) throw fail('expected bucket <name> <capacity> <refill> <per>')
      if (!NAME.test(f[1])) throw fail(`invalid policy name ${f[1]}`)
      const capacity = num(f[2], 'capacity', 1)
      const refill = num(f[3], 'refill', 0)
      const per = num(f[4], 'per', 1)
      if (policies.has(f[1])) throw fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { name: f[1], kind: 'bucket', capacity, refill, per, st: new Map() })
    } else if (d === 'window') {
      if (f.length !== 4) throw fail('expected window <name> <limit> <span>')
      if (!NAME.test(f[1])) throw fail(`invalid policy name ${f[1]}`)
      const limit = num(f[2], 'limit', 0)
      const span = num(f[3], 'span', 1)
      if (policies.has(f[1])) throw fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { name: f[1], kind: 'window', limit, span, st: new Map() })
    } else if (d === 'route') {
      if (f.length < 3) throw fail('expected route <prefix> <policy>...')
      if (!NAME.test(f[1])) throw fail(`invalid route prefix ${f[1]}`)
      if (routes.has(f[1])) throw fail(`prefix ${f[1]} is routed twice`)
      const list = []
      for (const p of f.slice(2)) {
        if (!policies.has(p)) throw fail(`unknown policy ${p}`)
        list.push(policies.get(p))
      }
      routes.set(f[1], list)
    } else if (d === 'event') {
      if (f.length !== 3) throw fail('expected event <tick> <key>')
      const tick = num(f[1], 'tick', 0)
      if (!NAME.test(f[2])) throw fail(`invalid key ${f[2]}`)
      if (lastTick !== null && tick < lastTick) throw fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, key: f[2] })
    } else {
      throw fail(`unknown directive ${d}`)
    }
  }
  return { routes, events }
}

function advance(p, key, tick) {
  let s = p.st.get(key)
  if (p.kind === 'bucket') {
    const max = p.capacity * p.per
    if (!s) {
      s = { v: max, last: tick }
      p.st.set(key, s)
    } else {
      s.v += p.refill * (tick - s.last)
      if (s.v > max) s.v = max
      s.last = tick
    }
  } else {
    if (!s) {
      s = { ticks: [] }
      p.st.set(key, s)
    }
    const cut = tick - p.span
    while (s.ticks.length && s.ticks[0] <= cut) s.ticks.shift()
  }
  return s
}

