  const { routes, events } = parse(text)
  const out = []
  const sums = new Map()
  let ta = 0, td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const pre of routes.keys()) {
      if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    }
    const list = best === null ? [] : routes.get(best)
    const states = list.map((p) => advance(p, key, tick))
    let denier = null
    for (let i = 0; i < list.length; i++) {
      const p = list[i], s = states[i]
      const ok = p.kind === 'bucket' ? s.v >= p.per : BigInt(s.ticks.length) < p.limit
      if (!ok) { denier = p; break }
    }
