      for (let i = 0; i < list.length; i++) {
        if (list[i].kind === 'bucket') states[i].v -= list[i].per
        else states[i].ticks.push(tick)
      }
    }
    const c = sums.get(key) || { a: 0, d: 0 }
    sums.set(key, c)
    if (denier) { c.d++; td++ } else { c.a++; ta++ }
    out.push(`${tick} ${key} ${denier ? 'deny ' + denier.name : 'allow'}`)
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  const keys = [...sums.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  return keys.map((k) => `${k} allowed=${sums.get(k).a} denied=${sums.get(k).d}\n`).join('') +
    `total allowed=${ta} denied=${td}\n`
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}
try {
  const text = readFileSync(0, 'utf8')
  process.stdout.write(run(args[0], text))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
