  for (const c of cont) if (min === null || counts.get(c) < min) min = counts.get(c)
  let tied = [...cont].filter((c) => counts.get(c) === min)
  while (tied.length > 1) {
    let r = 0
    for (; r < history.length; r++) {
      const vs = tied.map((c) => history[r].get(c))
      if (vs.some((v) => v !== vs[0])) {
        const m = vs.reduce((a, b) => (b < a ? b : a))
        tied = tied.filter((c) => history[r].get(c) === m)
        break
      }
    }
