cat > src/scan.js <<'EOF'
export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

export function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const toks = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const advN = (k) => { for (let j = 0; j < k; j++) adv() }

  // digit run with underscores only between digits; returns end index
  const run = (j, ok) => {
    while (j < n) {
      if (ok(s[j])) j++
      else if (s[j] === '_' && j > 0 && ok(s[j - 1]) && ok(s[j + 1])) j++
      else break
    }
    return j
  }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      const sl = line, sc = col
      advN(2)
      let depth = 1
      while (i < n && depth > 0) {
        if (s[i] === '/' && s[i + 1] === '*') { advN(2); depth++ }
        else if (s[i] === '*' && s[i + 1] === '/') { advN(2); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    const sl = line, sc = col
    const push = (kind, body) => toks.push({ line: sl, col: sc, kind, body })

    if (isIdStart(c)) {
      if (c === 'r' && s[i + 1] === '"') {
        advN(2)
        let v = ''
        while (i < n && s[i] !== '"') v += adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        adv()
        push('rawstring', JSON.stringify(v))
        continue
      }
      let j = i
      while (j < n && isIdChar(s[j])) j++
      const w = s.slice(i, j).join('')
      advN(j - i)
      push(KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      continue
    }
    if (isDigit(c)) {
      let j = i
      let bad = false
      const p = (s[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        const ok = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        j = i + 2
        if (!ok(s[j])) bad = true
        else j = run(j, ok)
      } else {
        j = run(i, isDigit)
        if (s[j] === '.' && isDigit(s[j + 1])) j = run(j + 1, isDigit)
        if (s[j] === 'e' || s[j] === 'E') {
          let k = j + 1
          if (s[k] === '+' || s[k] === '-') k++
          if (isDigit(s[k])) j = run(k, isDigit)
        }
      }
      if (isIdChar(s[j])) bad = true
      if (bad) {
        while (isIdChar(s[j])) j++
        throw new ScanError(sl, sc, `invalid number ${s.slice(i, j).join('')}`)
      }
      const w = s.slice(i, j).join('')
      advN(j - i)
      push('number', w)
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = s[i]
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d === '"') { adv(); break }
        if (d !== '\\') { v += adv(); continue }
        const el = line, ec = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = s[i]
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (e in simple) { adv(); v += simple[e]; continue }
        if (e === 'x') {
          if (isHex(s[i + 1]) && isHex(s[i + 2])) {
            v += String.fromCharCode(parseInt(s[i + 1] + s[i + 2], 16))
            advN(3)
            continue
          }
        } else if (e === 'u' && s[i + 1] === '{') {
          let j = i + 2
          while (isHex(s[j])) j++
          if (j > i + 2 && s[j] === '}') {
            const cp = parseInt(s.slice(i + 2, j).join(''), 16)
            if (cp <= 0x10ffff) {
              v += String.fromCodePoint(cp)
              advN(j + 1 - i)
              continue
            }
          }
        }
        throw new ScanError(el, ec, `invalid escape \\${e}`)
      }
      push('string', JSON.stringify(v))
      continue
    }
    const two = c + (s[i + 1] || '')
    if (PUNCT2.includes(two)) { advN(2); push('punct', two); continue }
    if (PUNCT1.includes(c)) { adv(); push('punct', c); continue }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return toks
}
EOF
