      while (i < n && depth > 0) {
        if (s[i] === '/' && s[i + 1] === '*') { advN(2); depth++ }
        else if (s[i] === '*' && s[i + 1] === '/') { advN(2); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    const sl = line, sc = col
    const push = (kind, body) => toks.push({ line: sl, col: sc, kind, body })

    if (isIdStart(c)) {
      if (c === 'r' && s[i + 1] === '"') {
        advN(2)
