        while (i < n && s[i] !== '"') v += adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        adv()
        push('rawstring', JSON.stringify(v))
        continue
      }
      let j = i
      while (j < n && isIdChar(s[j])) j++
