        if (!ok(s[j])) bad = true
        else j = run(j, ok)
      } else {
        j = run(i, isDigit)
        if (s[j] === '.' && isDigit(s[j + 1])) j = run(j + 1, isDigit)
        if (s[j] === 'e' || s[j] === 'E') {
          let k = j + 1
