              continue
            }
          }
        }
        throw new ScanError(el, ec, `invalid escape \\${e}`)
      }
      push('string', JSON.stringify(v))
      continue
    }
    const two = c + (s[i + 1] || '')
    if (PUNCT2.includes(two)) { advN(2); push('punct', two); continue }
    if (PUNCT1.includes(c)) { adv(); push('punct', c); continue }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return toks
}
