export function merge(mode, mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)].sort((a, b) => a.bs - b.bs || a.who - b.who)
  const sides = [mine, theirs]
  const items = [] // {kind, lines} or conflict
  let pos = 0, k = 0
  while (k < all.length) {
    const first = all[k++]
    const group = [first]
    let end = first.be
    while (k < all.length && all[k].bs <= end) { end = Math.max(end, all[k].be); group.push(all[k++]) }
    const start = first.bs
    if (start > pos) items.push({ kind: 'stable', lines: base.slice(pos, start) })
    const rep = who => {
      const cs = group.filter(c => c.who === who)
      if (!cs.length) return base.slice(start, end)
      const bs = Math.min(...cs.map(c => c.bs)), be = Math.max(...cs.map(c => c.be))
      const ss = cs[0].ss - (bs - start), se = cs[cs.length - 1].se + (end - be)
      return sides[who].slice(ss, se)
    }
    const m = rep(0), t = rep(1), b = base.slice(start, end)
    if (eq(m, t)) items.push({ kind: 'both', lines: m })
    else if (eq(m, b)) items.push({ kind: 'theirs', lines: t })
    else if (eq(t, b)) items.push({ kind: 'mine', lines: m })
    else items.push({ kind: 'conflict', m, b, t })
    pos = end
  }
  if (pos < base.length) items.push({ kind: 'stable', lines: base.slice(pos) })
  const out = []
  let conflict = false
  for (const it of items) {
    if (it.kind === 'conflict') {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${it.m.length} base=${it.b.length} theirs=${it.t.length}`)
      else {
        out.push('<<<<<<< mine', ...it.m)
        if (mode === 'merge') out.push('||||||| base', ...it.b)
        out.push('=======', ...it.t, '>>>>>>> theirs')
      }
    } else if (mode === 'regions') out.push(`${it.kind} ${it.lines.length}`)
    else out.push(...it.lines)
  }
  return { out, conflict }
}
