const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function parse(s) {
  const r = { scheme: null, authority: null, path: '', query: null, fragment: null }
  let rest = s
  const m = /^([^:/?#]+):/.exec(rest)
  if (m) {
    r.scheme = m[1]
    rest = rest.slice(m[0].length)
  }
  const h = rest.indexOf('#')
  if (h >= 0) {
    r.fragment = rest.slice(h + 1)
    rest = rest.slice(0, h)
  }
  const q = rest.indexOf('?')
  if (q >= 0) {
    r.query = rest.slice(q + 1)
    rest = rest.slice(0, q)
  }
  if (rest.startsWith('//')) {
    const e = rest.indexOf('/', 2)
    r.authority = e < 0 ? rest.slice(2) : rest.slice(2, e)
    rest = e < 0 ? '' : rest.slice(e)
  }
  r.path = rest
  return r
}

function splitAuthority(a) {
  let userinfo = null
  const at = a.lastIndexOf('@')
  if (at >= 0) {
    userinfo = a.slice(0, at)
    a = a.slice(at + 1)
  }
  const colon = a.indexOf(':', a.lastIndexOf(']') + 1)
  if (colon < 0) return { userinfo, host: a, port: null }
  return { userinfo, host: a.slice(0, colon), port: a.slice(colon + 1) }
}

const truncated = (s) => /%(?![0-9A-Fa-f]{2})/.test(s)

export function checkPercent(r) {
  const parts = [['path', r.path]]
  if (r.authority !== null) {
    const a = splitAuthority(r.authority)
    parts.push(['userinfo', a.userinfo], ['host', a.host])
  }
  parts.push(['query', r.query], ['fragment', r.fragment])
  for (const [name, v] of parts) if (v !== null && truncated(v)) return name
  return null
}

function normPct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, hx) => {
    const c = String.fromCharCode(parseInt(hx, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + hx.toUpperCase()
  })
}

const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

export function removeDots(path) {
  let input = path
  const out = []
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out.pop()
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out.push(seg)
      input = i < 0 ? '' : input.slice(i)
    }
  }
  return out.join('')
}

export function normalize(r) {
  const scheme = r.scheme === null ? null : lowerAscii(r.scheme)
  let auth = null
  if (r.authority !== null) {
    const a = splitAuthority(r.authority)
    let s = ''
    if (a.userinfo !== null) s += normPct(a.userinfo) + '@'
    s += lowerAscii(normPct(a.host))
    if (a.port !== null && a.port !== '' && !(scheme !== null && DEFAULT_PORTS[scheme] === a.port)) {
      s += ':' + normPct(a.port)
    }
    auth = s
  }
  let path = removeDots(normPct(r.path))
  if (auth !== null && path === '') path = '/'
  let out = ''
  if (scheme !== null) out += scheme + ':'
  if (auth !== null) out += '//' + auth
  out += path
  if (r.query !== null) out += '?' + normPct(r.query)
  if (r.fragment !== null) out += '#' + normPct(r.fragment)
  return out
}

export function resolve(base, ref) {
  const t = { scheme: null, authority: null, path: '', query: null, fragment: ref.fragment }
  if (ref.scheme !== null) {
    Object.assign(t, ref)
  } else if (ref.authority !== null) {
    Object.assign(t, ref, { scheme: base.scheme })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== null ? ref.query : base.query
    } else {
      t.query = ref.query
      if (ref.path.startsWith('/')) t.path = ref.path
      else if (base.authority !== null && base.path === '') t.path = '/' + ref.path
      else {
        const i = base.path.lastIndexOf('/')
        t.path = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
      }
    }
  }
  return t
}
