import { readFileSync } from 'node:fs'
import { parse, normalize, resolve, checkPercent } from './uri.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const out = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const fail = (msg) => {
    process.stderr.write(`error: line ${n}: ${msg}\n`)
    process.exit(2)
  }
  let target
  if (mode === 'normalize') {
    target = parse(lines[i])
  } else {
    const sp = lines[i].indexOf(' ')
    if (sp < 0) fail('expected a base and a reference')
    const base = parse(lines[i].slice(0, sp))
    if (base.scheme === null) fail('the base has no scheme')
    target = resolve(base, parse(lines[i].slice(sp + 1)))
  }
  const bad = checkPercent(target)
  if (bad) fail(`the ${bad} has a truncated percent-encoding`)
  out.push(normalize(target))
}
if (out.length) process.stdout.write(out.join('\n') + '\n')
