  }
  while (i < n && j < m) {
    if (base[i] === side[j]) { flush(); i++; j++; ci = i; cj = j }
    else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !modes.includes(mode)) fail('usage: cli.js merge|merge2|regions')
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) l === '%%%' ? docs.push([]) : docs[docs.length - 1].push(l)
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs
