  all.sort((a, b) => a.bs - b.bs) // stable: mine first on ties
  const out = []
  const info = []
  let conflict = false
  let pos = 0
  const stable = end => {
    if (end > pos) { out.push(...base.slice(pos, end)); info.push(`stable ${end - pos}`) }
  }
  let k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) { re = Math.max(re, all[k].be); group.push(all[k++]) }
