      const g = group.filter(c => c.who === who)
      if (!g.length) return base.slice(rs, re)
      const s = Math.min(...g.map(c => c.ss)) - (Math.min(...g.map(c => c.bs)) - rs)
      const e = Math.max(...g.map(c => c.se)) + (re - Math.max(...g.map(c => c.be)))
