    }
    const M = side('m', mine), T = side('t', theirs), B = base.slice(rs, re)
    let res, label
    if (same(M, T)) { res = M; label = 'both' }
    else if (same(M, B)) { res = T; label = 'theirs' }
    else if (same(T, B)) { res = M; label = 'mine' }
    if (label) {
      out.push(...res)
      info.push(`${label} ${res.length}`)
    } else {
      conflict = true
      out.push('<<<<<<< mine', ...M)
      if (mode === 'merge') out.push('||||||| base', ...B)
      out.push('=======', ...T, '>>>>>>> theirs')
      info.push(`conflict mine=${M.length} base=${B.length} theirs=${T.length}`)
    }
    pos = re
  }
  stable(base.length)
  const result = mode === 'regions' ? info : out
  process.stdout.write(result.map(l => l + '\n').join(''))
  process.exitCode = conflict ? 1 : 0
}
main()
