class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

const newTable = () => ({ t: 'table', map: new Map(), headerDefined: false })

class Parser {
  constructor(line) { this.s = line; this.i = 0 }
  peek() { return this.s[this.i] }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() { const c = this.s[this.i]; return c === undefined || c === '#' || c === ';' }

  basicString() {
    this.i++
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      if (c === '"') { this.i++; return out }
      if (c === '\\') {
        const e = this.s[this.i + 1]
        if (e === undefined) fail('unterminated string')
        const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(simple, e)) { out += simple[e]; this.i += 2; continue }
        if (e === 'u') {
          const h = this.s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 6
          continue
        }
        fail('invalid escape \\' + String.fromCodePoint(this.s.codePointAt(this.i + 1)))
      }
      out += c
      this.i++
    }
  }

  literalString() {
    const end = this.s.indexOf("'", this.i + 1)
    if (end < 0) fail('unterminated string')
    const v = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return v
  }

  // Returns a name or null when none starts here.
  name() {
    const c = this.peek()
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    if (!isNameChar(c)) return null
    const st = this.i
    while (isNameChar(this.s[this.i])) this.i++
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = []
    for (;;) {
      this.ws()
      const n = this.name()
      if (n === null) fail('expected a name')
      parts.push(n)
      this.ws()
      if (this.peek() === '.') { this.i++; continue }
      return parts
    }
  }

  value(prefix) {
    this.ws()
    const c = this.peek()
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basicString() }
    if (c === "'") return { t: 'string', v: this.literalString() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    const digits = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${digits}$`).test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${digits}(?:\\.${digits}(?:[eE][+-]?${digits})?|[eE][+-]?${digits})$`).test(w)) {
      return { t: 'float', v: Number(w.replace(/_/g, '')) }
    }
    fail('invalid value ' + w)
  }

  array(prefix) {
    this.i++
    const items = []
    this.ws()
    if (this.peek() === ']') { this.i++; return { t: 'array', items, aot: false } }
    for (;;) {
      items.push(this.value(prefix))
      this.ws()
      const c = this.peek()
      if (c === ',') {
        this.i++
        this.ws()
        if (this.peek() === ']') { this.i++; break }
        continue
      }
      if (c === ']') { this.i++; break }
      fail('unterminated array')
    }
    return { t: 'array', items, aot: false }
  }

  inline(prefix) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.peek() === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const key = this.dotted()
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value([...prefix, ...key])
      assign(tbl, prefix, key, v)
      this.ws()
      const c = this.peek()
      if (c === ',') { this.i++; continue }
      if (c === '}') { this.i++; return tbl }
      fail('unterminated inline table')
    }
  }
}

// Step into a child as a container table; creates absent ones.
function descend(tbl, name, path) {
  let child = tbl.map.get(name)
  if (!child) { child = newTable(); tbl.map.set(name, child) }
  if (child.t === 'table') return child
  if (child.t === 'array' && child.aot) return child.items[child.items.length - 1]
  return fail(`${path.join('.')} is not a table`)
}

function assign(tbl, prefix, key, v) {
  let cur = tbl
  const path = [...prefix]
  for (let k = 0; k < key.length - 1; k++) {
    path.push(key[k])
    cur = descend(cur, key[k], path)
  }
  path.push(key[key.length - 1])
  if (cur.map.has(key[key.length - 1])) fail(`key ${path.join('.')} is defined twice`)
  cur.map.set(key[key.length - 1], v)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  lines.forEach((line, idx) => {
    try {
      const p = new Parser(line)
      p.ws()
      const c = p.peek()
      if (c === undefined || c === '#' || c === ';') return
      if (c === '[') {
        const dbl = line[p.i + 1] === '['
        p.i += dbl ? 2 : 1
        const parts = p.dotted()
        p.ws()
        if (p.peek() !== ']') fail('unterminated table header')
        p.i++
        if (dbl) {
          if (p.peek() !== ']') fail('unterminated table header')
          p.i++
        }
        p.ws()
        if (!p.atEnd()) fail('trailing text after a table header')
        let t = root
        const path = []
        for (let k = 0; k < parts.length - 1; k++) {
          path.push(parts[k])
          t = descend(t, parts[k], path)
        }
        const last = parts[parts.length - 1]
        path.push(last)
        const ex = t.map.get(last)
        if (dbl) {
          const fresh = newTable()
          fresh.headerDefined = true
          if (!ex) t.map.set(last, { t: 'array', items: [fresh], aot: true })
          else if (ex.t === 'array' && ex.aot) ex.items.push(fresh)
          else fail(`${path.join('.')} is not an array of tables`)
          cur = fresh
        } else {
          if (!ex) {
            const nt = newTable()
            nt.headerDefined = true
            t.map.set(last, nt)
            cur = nt
          } else if (ex.t === 'table') {
            if (ex.headerDefined) fail(`table ${path.join('.')} is defined twice`)
            ex.headerDefined = true
            cur = ex
          } else fail(`${path.join('.')} is not a table`)
        }
        curPath = path
        return
      }
      const key = p.dotted()
      p.ws()
      if (p.peek() !== '=') fail('expected key = value')
      p.i++
      const v = p.value([...curPath, ...key])
      p.ws()
      if (!p.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, key, v)
    } catch (e) {
      if (e instanceof Fail) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}

function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (m) => [...m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  switch (n.t) {
    case 'table': {
      const ks = sortedKeys(n.map)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(n.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!n.items.length) return '[]'
      return '[\n' + n.items.map((v) => pad + toJson(v, ind + 1)).join(',\n') + '\n' + end + ']'
    case 'integer': return n.v.toString()
    case 'float': return JSON.stringify(n.v)
    default: return JSON.stringify(n.v)
  }
}

function keys(n, path, out) {
  if (n.t === 'table') {
    for (const k of sortedKeys(n.map)) {
      const c = n.map.get(k)
      const p = path === null ? k : `${path}.${k}`
      out.push(`${p} ${c.t}`)
      keys(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${c.t}`)
      keys(c, p, out)
    })
  }
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
try {
  const root = parse(readFileSync(0, 'utf8'))
  if (mode === 'json') process.stdout.write(toJson(root, 0) + '\n')
  else {
    const out = []
    keys(root, null, out)
    process.stdout.write(out.map((l) => l + '\n').join(''))
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
"}

