      const c = n.map.get(k)
      const p = path === null ? k : `${path}.${k}`
      out.push(`${p} ${c.t}`)
      keys(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${c.t}`)
