        case 'r': out += '\r'; break
        case '0': out += '\0'; break
        case 'u': {
          const h = this.s.slice(this.i, this.i + 4)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 4
          break
        }
        default:
          this.fail(`invalid escape \\${e}`)
      }
    }
  }
  name() {
    const c = this.peek()
    if (c === '"' || c === "'") return this.quoted()
    if (!isNameChar(c)) this.fail('expected a name')
    const st = this.i
    while (isNameChar(this.s[this.i])) this.i++
    return this.s.slice(st, this.i)
  }
  dotted() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() !== '.') {
        this.i = save
        return names
      }
      this.i++
      this.ws()
      names.push(this.name())
    }
  }
  value(prefix) {
    const c = this.peek()
    if (c === undefined || c === ',' || c === ']' || c === '}' || c === '#' || c === ';') this.fail('expected a value')
    if (c === '"' || c === "'") return { type: 'string', v: this.quoted() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) this.i++
    const t = this.s.slice(st, this.i)
    if (t === 'true' || t === 'false') return { type: 'boolean', v: t === 'true' }
    if (INT.test(t)) return { type: 'integer', v: Number(t.replace(/_/g, '')) }
    if (FLOAT.test(t)) return { type: 'float', v: Number(t.replace(/_/g, '')) }
    this.fail(`invalid value ${t}`)
  }
  array(prefix) {
    this.i++
    const items = []
    this.ws()
    if (this.peek() === ']') {
      this.i++
      return { type: 'array', items, aot: false }
    }
    for (;;) {
      this.ws()
      if (this.i >= this.s.length || this.atEnd()) this.fail(items.length ? 'unterminated array' : 'unterminated array')
      items.push(this.value(prefix))
      this.ws()
      const c = this.peek()
      if (c === ']') {
        this.i++
        return { type: 'array', items, aot: false }
      }
      if (c !== ',') this.fail('unterminated array')
      this.i++
      this.ws()
      if (this.peek() === ']') {
        this.i++
        return { type: 'array', items, aot: false }
      }
    }
  }
  inline(prefix) {
    this.i++
    const t = newTable()
    this.ws()
    if (this.peek() === '}') {
      this.i++
      return t
    }
    for (;;) {
      this.ws()
      if (this.i >= this.s.length || this.atEnd()) this.fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.i >= this.s.length) this.fail('unterminated inline table')
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value(prefix)
      assign(t, prefix, names, v, this)
      this.ws()
      const c = this.peek()
      if (c === '}') {
        this.i++
        return t
      }
      if (c !== ',') this.fail('unterminated inline table')
      this.i++
    }
  }
}

function assign(table, prefix, names, v, p) {
  let cur = table
  let path = prefix.slice()
  for (let k = 0; k < names.length - 1; k++) {
    path.push(names[k])
    let next = cur.m.get(names[k])
    if (next === undefined) {
      next = newTable()
      cur.m.set(names[k], next)
    } else if (next.type === 'array' && next.aot) {
      next = next.items[next.items.length - 1]
    } else if (next.type !== 'table') {
      p.fail(`${path.join('.')} is not a table`)
    }
    cur = next
  }
  const last = names[names.length - 1]
  path.push(last)
  if (cur.m.has(last)) p.fail(`key ${path.join('.')} is defined twice`)
  cur.m.set(last, v)
}

export function parseDocument(lines) {
  const root = newTable()
  let cur = root
  let curPath = []
  lines.forEach((line, idx) => {
    const p = new LineParser(line, idx + 1)
    p.ws()
    if (p.i >= line.length || line[p.i] === '#' || line[p.i] === ';') return
    if (line[p.i] === '[') {
      p.i++
      const aot = p.peek() === '['
      if (aot) p.i++
      p.ws()
      const names = p.dotted()
      p.ws()
      for (let k = 0; k < (aot ? 2 : 1); k++) {
        if (p.peek() !== ']') p.fail('unterminated table header')
        p.i++
      }
      p.ws()
      if (!p.atEnd()) p.fail('trailing text after a table header')
      let t = root
      const path = []
      for (let k = 0; k < names.length - 1; k++) {
        path.push(names[k])
        let next = t.m.get(names[k])
        if (next === undefined) {
          next = newTable()
          t.m.set(names[k], next)
        } else if (next.type === 'array' && next.aot) {
          next = next.items[next.items.length - 1]
        } else if (next.type !== 'table') {
          p.fail(`${path.join('.')} is not a table`)
        }
        t = next
      }
      const last = names[names.length - 1]
      path.push(last)
      const ps = path.join('.')
      const ex = t.m.get(last)
      if (aot) {
        let arr = ex
        if (ex === undefined) {
          arr = { type: 'array', items: [], aot: true }
          t.m.set(last, arr)
        } else if (ex.type !== 'array' || !ex.aot) {
          p.fail(`${ps} is not an array of tables`)
        }
        const nt = newTable()
        arr.items.push(nt)
        cur = nt
      } else {
        if (ex === undefined) {
          const nt = newTable()
          nt.defined = true
          t.m.set(last, nt)
          cur = nt
        } else if (ex.type !== 'table') {
          p.fail(`${ps} is not a table`)
        } else {
          if (ex.defined) p.fail(`table ${ps} is defined twice`)
          ex.defined = true
          cur = ex
        }
      }
      curPath = path
      return
    }
    const names = p.dotted()
    p.ws()
    if (p.peek() !== '=') p.fail('expected key = value')
    p.i++
    p.ws()
    const v = p.value([...curPath, ...names.slice(0, -1)].slice(0, 0).concat(curPath, names))
    p.ws()
    if (!p.atEnd()) p.fail('trailing text after a value')
    assign(cur, curPath, names, v, p)
  })
  return root
}
