{"file_path":"src/parse.js","content":"function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^\d+(\.\d+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] })
      i += m[0].length
    } else return null
  }
  return toks
}

// Returns an AST, or null when the grammar rejects the text.
export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const fail = new Error('syntax')
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { t: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (isOp('-')) { p++; return { t: 'neg', x: unary() } }
    if (isOp('+')) { p++; return { t: 'pos', x: unary() } }
    return atom()
  }
  function atom() {
    if (p >= toks.length) throw fail
    const tk = toks[p++]
    if (tk.k === 'num') return { t: 'num', v: tk.v }
    if (tk.k === 'op') {
      if (tk.v !== '(') throw fail
      const e = cmp()
      if (!isOp(')')) throw fail
      p++
      return e
    }
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw fail
        }
      }
      return { t: 'call', name: tk.v.toUpperCase(), args }
    }
    const up = tk.v.toUpperCase()
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') throw fail
      return { t: 'range', a: tk.v, b: toks[p++].v }
    }
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', name: tk.v }
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e === fail) return null
    throw e
  }
}
"}

{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'
import { parseAddr } from './addr.js'

class Err {
  constructor(token) { this.token = token }
}
const ERR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const E = Object.fromEntries(ERR_TOKENS.map((t) => [t, new Err(t)]))
const DIV = E['#DIV/0!']
const REF = E['#REF!']
const VALUE = E['#VALUE!']
const CYCLE = E['#CYCLE!']
const NAME = E['#NAME?']
const ERR = E['#ERR!']

const rank = (v) => (typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2)

function toNum(v) {
  if (v instanceof Err) return v
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  return VALUE
}

function finite(n) {
  return Number.isFinite(n) ? n : DIV
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.stack = new Set()
  }

  format(v) {
    if (v instanceof Err) return v.token
    if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
    if (typeof v === 'number') return String(Number(v.toPrecision(10)))
    return v
  }

  get(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.stack.has(key)) return CYCLE
    const cell = this.cells.get(key)
    if (!cell) return 0
    this.stack.add(key)
    const v = this.compute(cell.content)
    this.stack.delete(key)
    this.memo.set(key, v)
    return v
  }

  compute(content) {
    if (content[0] === '=') {
      const ast = parseFormula(content.slice(1))
      if (!ast) return ERR
      return this.ev(ast)
    }
    if (content === '') return 0
    if (/^-?\d+(\.\d+)?$/.test(content)) return Number(content)
    if (E[content]) return E[content]
    return content
  }

  rangeCells(n) {
    const a = parseAddr(n.a)
    const b = parseAddr(n.b)
    if (!a || !b) return REF
    const out = []
    for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
      for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++)
        out.push(this.get(parseAddr(null, c, r).key))
    return out
  }

  // single value for non-variadic positions
  one(n) {
    if (n.t !== 'range') return this.ev(n)
    const vs = this.rangeCells(n)
    if (vs instanceof Err) return vs
    const e = vs.find((v) => v instanceof Err)
    if (e) return e
    return vs.length === 1 ? vs[0] : ERR
  }

  ev(n) {
    switch (n.t) {
      case 'num': return n.v
      case 'bool': return n.v
      case 'range': return ERR
      case 'ref': {
        const a = parseAddr(n.name)
        return a ? this.get(a.key) : REF
      }
      case 'neg': {
        const v = toNum(this.ev(n.x))
        return v instanceof Err ? v : -v
      }
      case 'pos': return toNum(this.ev(n.x))
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return ERR
  }

  bin(n) {
    const lv = this.ev(n.l)
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      if (lv instanceof Err) return lv
      const rv = this.ev(n.r)
      if (rv instanceof Err) return rv
      let c
      const ra = rank(lv)
      const rb = rank(rv)
      if (ra !== rb) c = ra < rb ? -1 : 1
      else if (ra === 1) c = cmpCodePoints(lv, rv)
      else c = lv < rv ? -1 : lv > rv ? 1 : 0
      switch (n.op) {
        case '=': return c === 0
        case '<>': return c !== 0
        case '<': return c < 0
        case '<=': return c <= 0
        case '>': return c > 0
        default: return c >= 0
      }
    }
    const l = toNum(lv)
    if (l instanceof Err) return l
    const r = toNum(this.ev(n.r))
    if (r instanceof Err) return r
    switch (n.op) {
      case '+': return finite(l + r)
      case '-': return finite(l - r)
      case '*': return finite(l * r)
      case '/': return r === 0 ? DIV : finite(l / r)
      default: return finite(Math.pow(l, r))
    }
  }

  call(n) {
    const name = n.name
    const k = n.args.length
    if (name === 'IF') {
      if (k !== 3) return ERR
      const c = this.one(n.args[0])
      if (c instanceof Err) return c
      let t
      if (typeof c === 'boolean') t = c
      else if (typeof c === 'number') t = c !== 0
      else return VALUE
      return this.one(n.args[t ? 1 : 2])
    }
    if (name === 'ABS') {
      if (k !== 1) return ERR
      const v = toNum(this.one(n.args[0]))
      return v instanceof Err ? v : Math.abs(v)
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return NAME
    if (k < 1) return ERR
    const vals = []
    for (const a of n.args) {
      if (a.t === 'range') {
        const vs = this.rangeCells(a)
        if (vs instanceof Err) return vs
        for (const v of vs) {
          if (v instanceof Err) return v
          vals.push(v)
        }
      } else {
        const v = this.ev(a)
        if (v instanceof Err) return v
        vals.push(v)
      }
    }
    if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x instanceof Err) return x
      nums.push(x)
    }
    switch (name) {
