{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'
import { parseAddr } from './addr.js'

class Err {
  constructor(token) { this.token = token }
}
const ERR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const E = Object.fromEntries(ERR_TOKENS.map((t) => [t, new Err(t)]))
const DIV = E['#DIV/0!']
const REF = E['#REF!']
const VALUE = E['#VALUE!']
const CYCLE = E['#CYCLE!']
const NAME = E['#NAME?']
const ERR = E['#ERR!']

const rank = (v) => (typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2)

function toNum(v) {
  if (v instanceof Err) return v
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  return VALUE
}

function finite(n) {
  return Number.isFinite(n) ? n : DIV
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.stack = new Set()
  }

  format(v) {
    if (v instanceof Err) return v.token
    if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
    if (typeof v === 'number') return String(Number(v.toPrecision(10)))
    return v
  }

  get(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.stack.has(key)) return CYCLE
    const cell = this.cells.get(key)
    if (!cell) return 0
    this.stack.add(key)
    const v = this.compute(cell.content)
    this.stack.delete(key)
    this.memo.set(key, v)
    return v
  }

  compute(content) {
    if (content[0] === '=') {
      const ast = parseFormula(content.slice(1))
      if (!ast) return ERR
      return this.ev(ast)
    }
    if (content === '') return 0
    if (/^-?\d+(\.\d+)?$/.test(content)) return Number(content)
    if (E[content]) return E[content]
    return content
  }

  rangeCells(n) {
    const a = parseAddr(n.a)
    const b = parseAddr(n.b)
    if (!a || !b) return REF
    const out = []
    for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
      for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++)
        out.push(this.get(parseAddr(null, c, r).key))
    return out
  }

  // single value for non-variadic positions
  one(n) {
    if (n.t !== 'range') return this.ev(n)
    const vs = this.rangeCells(n)
    if (vs instanceof Err) return vs
    const e = vs.find((v) => v instanceof Err)
    if (e) return e
    return vs.length === 1 ? vs[0] : ERR
  }

  ev(n) {
    switch (n.t) {
      case 'num': return n.v
      case 'bool': return n.v
      case 'range': return ERR
      case 'ref': {
        const a = parseAddr(n.name)
        return a ? this.get(a.key) : REF
      }
      case 'neg': {
        const v = toNum(this.ev(n.x))
        return v instanceof Err ? v : -v
      }
      case 'pos': return toNum(this.ev(n.x))
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return ERR
  }

  bin(n) {
    const lv = this.ev(n.l)
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      if (lv instanceof Err) return lv
      const rv = this.ev(n.r)
      if (rv instanceof Err) return rv
      let c
      const ra = rank(lv)
      const rb = rank(rv)
      if (ra !== rb) c = ra < rb ? -1 : 1
      else if (ra === 1) c = cmpCodePoints(lv, rv)
      else c = lv < rv ? -1 : lv > rv ? 1 : 0
      switch (n.op) {
        case '=': return c === 0
        case '<>': return c !== 0
        case '<': return c < 0
        case '<=': return c <= 0
        case '>': return c > 0
        default: return c >= 0
      }
    }
    const l = toNum(lv)
    if (l instanceof Err) return l
    const r = toNum(this.ev(n.r))
    if (r instanceof Err) return r
    switch (n.op) {
      case '+': return finite(l + r)
      case '-': return finite(l - r)
      case '*': return finite(l * r)
      case '/': return r === 0 ? DIV : finite(l / r)
      default: return finite(Math.pow(l, r))
    }
  }

  call(n) {
    const name = n.name
    const k = n.args.length
    if (name === 'IF') {
      if (k !== 3) return ERR
      const c = this.one(n.args[0])
      if (c instanceof Err) return c
      let t
      if (typeof c === 'boolean') t = c
      else if (typeof c === 'number') t = c !== 0
