      return v instanceof Err ? v : Math.abs(v)
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return NAME
    if (k < 1) return ERR
    const vals = []
    for (const a of n.args) {
      if (a.t === 'range') {
        const vs = this.rangeCells(a)
        if (vs instanceof Err) return vs
        for (const v of vs) {
          if (v instanceof Err) return v
          vals.push(v)
        }
      } else {
        const v = this.ev(a)
        if (v instanceof Err) return v
        vals.push(v)
      }
    }
    if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x instanceof Err) return x
      nums.push(x)
    }
    switch (name) {
      case 'SUM': return finite(nums.reduce((a, b) => a + b, 0))
      case 'MIN': return Math.min(...nums)
      case 'MAX': return Math.max(...nums)
      default: return finite(nums.reduce((a, b) => a + b, 0) / nums.length)
    }
  }
}

function cmpCodePoints(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d < 0 ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}
