import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const fail = (n, r) => { throw new Fail(`error: line ${n}: ${r}`) }
const NAME = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function num(n, field, s, least) {
  if (!UINT.test(s) || BigInt(s) < BigInt(least)) fail(n, `${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let last = null
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const d = t[0]
    if (d === 'bucket' || d === 'window' || d === 'route') {
      const shape = d === 'bucket' ? 'bucket <name> <capacity> <refill> <per>'
        : d === 'window' ? 'window <name> <limit> <span>' : 'route <prefix> <policy>...'
      const ok = d === 'bucket' ? t.length === 5 : d === 'window' ? t.length === 4 : t.length >= 3
      if (!ok) fail(n, `expected ${shape}`)
      if (events.length) fail(n, 'declarations must come before the first event')
      if (d === 'route') {
        if (!NAME.test(t[1])) fail(n, `invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) fail(n, `prefix ${t[1]} is routed twice`)
        for (const p of t.slice(2)) if (!policies.has(p)) fail(n, `unknown policy ${p}`)
        routes.set(t[1], t.slice(2))
        return
      }
      if (!NAME.test(t[1])) fail(n, `invalid policy name ${t[1]}`)
      if (d === 'bucket') {
        const cap = num(n, 'capacity', t[2], 1), refill = num(n, 'refill', t[3], 0), per = num(n, 'per', t[4], 1)
        if (policies.has(t[1])) fail(n, `policy ${t[1]} is declared twice`)
