  }
}

function collectDeps(n, set) {
  if (n.k === 'ref') { if (n.a) set.add(key(n.a.col, n.a.row)) }
  else if (n.k === 'range') {
    if (n.a && n.b) {
      for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
